"april\",\"july\",\"church\",\"kornilov\",\"octplan\",\"congress\",\"culture\"],\"N05-K04\":[\"govt\",\"petrosoviet\",\"dual\",\"church\",\"octplan\",\"congress\",\"leftsr\",\"worker\",\"redguard\",\"constituent\",\"state-conference\"],\"N05-U01\":[\"february\",\"abdication\",\"april\",\"june\",\"republic\",\"october\",\"congress\",\"chronology\",\"stages-1917\"],\"N05-U02\":[\"abdication\",\"lenin\",\"july\",\"church\",\"kornilov\",\"octplan\",\"congress\"],\"N05-U03\":[\"culture\",\"poster\"],\"N05-U04\":[\"world\"],\"N05-U05\":[\"causes\",\"february\",\"govt\",\"petrosoviet\",\"dual\",\"lenin\",\"autumn\",\"octplan\",\"october\",\"redguard\",\"regions\"],\"N05-U06\":[\"warland\",\"compare\",\"source-criticism\"],\"N05-U07\":[\"govt\",\"parties\",\"chronology\",\"compare\",\"state-conference\",\"stages-1917\"],\"N05-U08\":[\"dual\",\"parties\",\"leftsr\",\"compare\",\"world\"],\"N05-U09\":[\"february\",\"abdication\",\"republic\",\"october\",\"chronology\",\"source-date\",\"stamp\",\"stages-1917\"],\"N05-U10\":[\"causes\",\"april\",\"june\",\"july\",\"kornilov\",\"autumn\",\"warland\",\"map\",\"world\",\"regions\",\"state-conference\"],\"N05-U11\":[\"source-date\",\"source-extract\",\"source-criticism\",\"culture\",\"poster\",\"state-conference\"],\"N05-U12\":[\"source-criticism\",\"research\"],\"N05-U13\":[\"source-extract\",\"map\",\"poster\",\"stamp\"],\"N05-U14\":[\"culture\",\"stamp\",\"research\"]}},\"CARD_CATEGORY_RULES\":{\"N05-K01\":\"Назовите событие или процесс, его участников и место в развитии сюжета.\",\"N05-K02\":\"Выделите опорную дату. Для российских событий 1917 года подпишите, в каком стиле дана дата.\",\"N05-K03\":\"Назовите конкретного деятеля, его должность или роль и связанное с ним действие.\",\"N05-K04\":\"Дайте определение по функции или существенному признаку понятия.\",\"N05-U01\":\"Назовите событие, дату и переход, который оно отмечает.\",\"N05-U02\":\"Свяжите действие или решение человека с его последствиями.\",\"N05-U03\":\"Назовите произведение и его создателя. Объясните характер изображения и историко-культурное значение.\",\"N05-U04\":\"Сопоставьте российский пример с международным документом или событием.\",\"N05-U05\":\"Различите действующих лиц, ход событий и результат.\",\"N05-U06\":\"Сформулируйте тезис и подтвердите его именованным фактом или источником.\",\"N05-U07\":\"Выберите один критерий и распределите по нему сведения из материала.\",\"N05-U08\":\"Сравните объекты по одному основанию и сформулируйте вывод.\",\"N05-U09\":\"Установите порядок или проверьте дату по названным ориентирам.\",\"N05-U10\":\"Назовите конкретную связь и подтвердите её фактами из материала.\",\"N05-U11\":\"Укажите автора, время или вид источника. Отделите утверждение автора от проверяемого факта.\",\"N05-U12\":\"Сформулируйте проверяемый вопрос, обоснуйте выбор документов и сопоставьте сведения.\",\"N05-U13\":\"Назовите существенный признак текста, карты или изображения и объясните его значение.\",\"N05-U14\":\"Объясните исследовательский или общественный смысл приведённого примера.\"},\"CARD_CATEGORY_ANSWERS\":{},\"CARD_MEDIA\":{\"version\":293,\"items\":{\"map\":[\"map\"],\"culture\":[\"kustodiev\",\"winter-palace\"],\"poster\":[\"poster\"],\"regions\":[\"second-universal\"]},\"assets\":{\"map\":{\"id\":\"map\",\"kind\":\"map\",\"src\":\"assets/revolution-1917/illustration-map.webp\",\"width\":624,\"height\":852,\"title\":\"Установление советской власти в стране. Карта и легенда\",\"sourceTitle\":\"Мединский, Торкунов. История России, 10 класс, 2024\",\"sourceUrl\":\"https://drive.google.com/file/d/1_lgbnh8ej2dy-jmC29rH1-2bvRgSc0h5/view\",\"page\":59,\"originalPage\":59,\"sha256\":\"9dcb16a42e6e979f58758f56a43154deda0c8bdd993ac5ce4ad489faa24f1352\"},\"kustodiev\":{\"id\":\"kustodiev\",\"kind\":\"artwork\",\"src\":\"assets/revolution-1917/illustration-kustodiev.webp\",\"width\":478,\"height\":300,\"title\":\"Б. М. Кустодиев. «Октябрь в Петрограде», 1927 год\",\"sourceTitle\":\"Мединский, Торкунов. История России, 10 класс, 2024\",\"sourceUrl\":\"https://drive.google.com/file/d/1_lgbnh8ej2dy-jmC29rH1-2bvRgSc0h5/view\",\"page\":51,\"originalPage\":51,\"sha256\":\"73887d30bee96a9b4c9ee72c30b4a16b217ff9e74b0e29ac59fa30bb215620cb\"},\"winter-palace\":{\"id\":\"winter-palace\",\"kind\":\"artwork\",\"src\":\"assets/revolution-1917/illustration-winter-palace.webp\",\"width\":648,\"height\":269,\"title\":\"Два изображения штурма Зимнего дворца, 1938 и 1939 годы\",\"sourceTitle\":\"Мединский, Торкунов. История России, 10 класс, 2024\",\"sourceUrl\":\"https://drive.google.com/file/d/1_lgbnh8ej2dy-jmC29rH1-2bvRgSc0h5/view\",\"page\":60,\"originalPage\":60,\"sha256\":\"4f9cf9abc32b4a933d6110c3fed6d93164acfd36bac5e962629cbcaa3482941b\"},\"poster\":{\"id\":\"poster\",\"kind\":\"artwork\",\"src\":\"assets/revolution-1917/illustration-poster.webp\",\"width\":295,\"height\":174,\"title\":\"Агитационный плакат И. Я. Билибина, 1917 год\",\"sourceTitle\":\"Мединский, Торкунов. История России, 10 класс, 2024\",\"sourceUrl\":\"https://drive.google.com/file/d/1_lgbnh8ej2dy-jmC29rH1-2bvRgSc0h5/view\",\"page\":61,\"originalPage\":61,\"sha256\":\"86df309d99e3dd53cc77fe99eec8ae3d6ca1d49162349c52909628381522423b\"},\"second-universal\":{\"id\":\"second-universal\",\"kind\":\"artwork\",\"src\":\"assets/revolution-1917/illustration-second-universal.webp\",\"width\":764,\"height\":1946,\"title\":\"Второй универсал Центральной рады\",\"sourceTitle\":\"«Русская воля», 6 (19) июля 1917, № 158, с. 2\",\"sourceUrl\":\"https://ruslitrev1917.imli.ru/files/attachment/832.pdf#page=2\",\"page\":null,\"originalPage\":null,\"sha256\":\"1153a5bc9a9409082a2077fe9011ac9f97303ac30ce068cfed74ffd7663f9575\"}}}},\"answers\":{\"N05-K01|causes\":{\"category_id\":\"N05-K01\",\"item_id\":\"causes\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Первая мировая война усилила хозяйственные и социальные противоречия: снабжение городов ухудшалось, цены росли, население уставало от войны. К этому добавились нерешённый аграрный вопрос и падение доверия к императорской власти. Перебои с хлебом в Петрограде стали непосредственным поводом массовых выступлений, но сами по себе не объясняют революцию. Решающий переход произошёл, когда к протестующим присоединились солдаты гарнизона: правительство лишилось возможности надёжно подавить выступления. В ответе отделяйте длительные причины от повода и от события, ускорившего падение монархии.\",\"supporting_span\":\"Первая мировая война усилила хозяйственные и социальные противоречия: снабжение городов ухудшалось, цены росли, население уставало от войны. К этому добавились нерешённый аграрный вопрос и падение доверия к императорской власти. Перебои с хлебом в Петрограде стали непосредственным поводом массовых выступлений, но сами по себе не объясняют революцию. Решающий переход произошёл, когда к протестующим присоединились солдаты гарнизона: правительство лишилось возможности надёжно подавить выступления. В ответе отделяйте длительные причины от повода и от события, ускорившего падение монархии.\",\"branch\":\"process\",\"official_exam_key\":false},\"N05-K01|february\":{\"category_id\":\"N05-K01\",\"item_id\":\"february\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"23 февраля начались массовые демонстрации; затем забастовки приобрели всеобщий характер. 27 февраля переход частей Петроградского гарнизона на сторону восставших изменил соотношение сил. В этот день возникли Временный комитет Государственной думы и Петроградский Совет. Эти органы имели разный состав и опору, поэтому падение старой власти не создало единого бесспорного центра новой. Все даты хронологии карточки до отдельного указания приводятся по старому стилю.\",\"supporting_span\":\"23 февраля начались массовые демонстрации; затем забастовки приобрели всеобщий характер. 27 февраля переход частей Петроградского гарнизона на сторону восставших изменил соотношение сил. В этот день возникли Временный комитет Государственной думы и Петроградский Совет. Эти органы имели разный состав и опору, поэтому падение старой власти не создало единого бесспорного центра новой. Все даты хронологии карточки до отдельного указания приводятся по старому стилю.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|abdication\":{\"category_id\":\"N05-K01\",\"item_id\":\"abdication\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"2 марта 1917 года Николай II отрёкся от престола за себя и сына в пользу брата Михаила Александровича. 3 марта Михаил поставил принятие верховной власти в зависимость от решения Учредительного собрания. Поэтому отречение Николая II и решение Михаила — два разных акта. Итогом стало прекращение монархического правления. Отдельная экзаменационная связь: А. И. Гучков — участник событий отречения; она проверяется в задании F4A38A и не означает, что Гучков был руководителем Петроградского Совета.\",\"supporting_span\":\"2 марта 1917 года Николай II отрёкся от престола за себя и сына в пользу брата Михаила Александровича. 3 марта Михаил поставил принятие верховной власти в зависимость от решения Учредительного собрания. Поэтому отречение Николая II и решение Михаила — два разных акта. Итогом стало прекращение монархического правления. Отдельная экзаменационная связь: А. И. Гучков — участник событий отречения; она проверяется в задании F4A38A и не означает, что Гучков был руководителем Петроградского Совета.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|govt\":{\"category_id\":\"N05-K01\",\"item_id\":\"govt\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Первое Временное правительство возглавил князь Г. Е. Львов. П. Н. Милюков стал министром иностранных дел, А. И. Гучков — военным и морским министром, А. Ф. Керенский — министром юстиции. Правительство объявило политическую амнистию и гражданские свободы, устраняло институты старой власти. Окончательное решение важнейших вопросов государственного устройства связывалось с Учредительным собранием. Продолжение войны и откладывание аграрного решения усиливали конфликт с ожиданиями солдат и крестьян.\",\"supporting_span\":\"Первое Временное правительство возглавил князь Г. Е. Львов. П. Н. Милюков стал министром иностранных дел, А. И. Гучков — военным и морским министром, А. Ф. Керенский — министром юстиции. Правительство объявило политическую амнистию и гражданские свободы, устраняло институты старой власти. Окончательное решение важнейших вопросов государственного устройства связывалось с Учредительным собранием. Продолжение войны и откладывание аграрного решения усиливали конфликт с ожиданиями солдат и крестьян.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|petrosoviet\":{\"category_id\":\"N05-K01\",\"item_id\":\"petrosoviet\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Петроградский Совет возник 27 февраля. Его председателем стал меньшевик Н. С. Чхеидзе; среди заместителей были А. Ф. Керенский и М. И. Скобелев. Совет опирался на рабочих и солдат и обладал реальным влиянием в гарнизоне. Приказ № 1 от 1 марта предусматривал выборные солдатские комитеты и регулировал отношения солдат с офицерами. Его значение — изменение традиционной системы подчинения и усиление роли Совета. Петроградский Совет нельзя смешивать с Временным комитетом Думы или Временным правительством.\",\"supporting_span\":\"Петроградский Совет возник 27 февраля. Его председателем стал меньшевик Н. С. Чхеидзе; среди заместителей были А. Ф. Керенский и М. И. Скобелев. Совет опирался на рабочих и солдат и обладал реальным влиянием в гарнизоне. Приказ № 1 от 1 марта предусматривал выборные солдатские комитеты и регулировал отношения солдат с офицерами. Его значение — изменение традиционной системы подчинения и усиление роли Совета. Петроградский Совет нельзя смешивать с Временным комитетом Думы или Временным правительством.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|dual\":{\"category_id\":\"N05-K01\",\"item_id\":\"dual\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Двоевластие — сосуществование Временного правительства и Советов как центров политической власти после Февральской революции. Правительство имело формальные государственные полномочия, а Совет — поддержку значительной части рабочих и солдат и возможность влиять на решения правительства. Это не два одинаковых кабинета министров. Согласие между ними было условным: разногласия по войне, земле и власти порождали кризисы. После июльских событий традиционно выделяется завершение периода двоевластия и усиление Временного правительства.\",\"supporting_span\":\"Двоевластие — сосуществование Временного правительства и Советов как центров политической власти после Февральской революции. Правительство имело формальные государственные полномочия, а Совет — поддержку значительной части рабочих и солдат и возможность влиять на решения правительства. Это не два одинаковых кабинета министров. Согласие между ними было условным: разногласия по войне, земле и власти порождали кризисы. После июльских событий традиционно выделяется завершение периода двоевластия и усиление Временного правительства.\",\"branch\":\"phenomenon\",\"official_exam_key\":false},\"N05-K01|parties\":{\"category_id\":\"N05-K01\",\"item_id\":\"parties\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"После Февраля кадеты приняли республиканскую форму правления и участвовали во Временном правительстве. Эсеры и меньшевики первоначально преобладали в Советах и поддерживали сотрудничество с правительством. Большевики после возвращения Ленина усилили курс на самостоятельную борьбу за власть. Поэтому «Советы» и «большевики» весной 1917 года не являются синонимами. Для сравнения партий используйте одинаковые критерии: отношение к правительству, войне, земле и переходу власти Советам.\",\"supporting_span\":\"После Февраля кадеты приняли республиканскую форму правления и участвовали во Временном правительстве. Эсеры и меньшевики первоначально преобладали в Советах и поддерживали сотрудничество с правительством. Большевики после возвращения Ленина усилили курс на самостоятельную борьбу за власть. Поэтому «Советы» и «большевики» весной 1917 года не являются синонимами. Для сравнения партий используйте одинаковые критерии: отношение к правительству, войне, земле и переходу власти Советам.\",\"branch\":\"process\",\"official_exam_key\":false},\"N05-K01|lenin\":{\"category_id\":\"N05-K01\",\"item_id\":\"lenin\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"После возвращения в Петроград в апреле Ленин выдвинул курс на переход от первого этапа революции ко второму. Апрельские тезисы требовали отказа от поддержки Временного правительства, перехода власти Советам и дальнейших социальных преобразований. В них ставились вопросы о земле, банках и войне. Значение тезисов — изменение политической стратегии большевиков: вместо поддержки существующей власти партия стала добиваться её замены. Ленин был лидером большевиков, а не главой Временного правительства.\",\"supporting_span\":\"После возвращения в Петроград в апреле Ленин выдвинул курс на переход от первого этапа революции ко второму. Апрельские тезисы требовали отказа от поддержки Временного правительства, перехода власти Советам и дальнейших социальных преобразований. В них ставились вопросы о земле, банках и войне. Значение тезисов — изменение политической стратегии большевиков: вместо поддержки существующей власти партия стала добиваться её замены. Ленин был лидером большевиков, а не главой Временного правительства.\",\"branch\":\"theoretical_position\",\"official_exam_key\":false},\"N05-K01|april\":{\"category_id\":\"N05-K01\",\"item_id\":\"april\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Нота министра иностранных дел П. Н. Милюкова от 18 апреля подтверждала обязательства России перед союзниками и продолжение войны. Это вступило в противоречие с массовыми ожиданиями мира и вызвало демонстрации. Милюков и Гучков покинули правительство. Создание первого коалиционного кабинета с участием социалистов расширило его партийную основу, но не разрешило главных противоречий. Причинная цепочка: позиция по войне → протест → отставки → изменение состава правительства.\",\"supporting_span\":\"Нота министра иностранных дел П. Н. Милюкова от 18 апреля подтверждала обязательства России перед союзниками и продолжение войны. Это вступило в противоречие с массовыми ожиданиями мира и вызвало демонстрации. Милюков и Гучков покинули правительство. Создание первого коалиционного кабинета с участием социалистов расширило его партийную основу, но не разрешило главных противоречий. Причинная цепочка: позиция по войне → протест → отставки → изменение состава правительства.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|june\":{\"category_id\":\"N05-K01\",\"item_id\":\"june\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"На I Всероссийском съезде Советов в июне преобладали эсеры и меньшевики. Большевики ещё не располагали там большинством. Однако демонстрация 18 июня показала заметную поддержку большевистских лозунгов в столице. Начатое на фронте наступление окончилось неудачей и усилило разочарование в продолжении войны. Не смешивайте состав съезда и настроение участников отдельной демонстрации: это разные показатели политического влияния.\",\"supporting_span\":\"На I Всероссийском съезде Советов в июне преобладали эсеры и меньшевики. Большевики ещё не располагали там большинством. Однако демонстрация 18 июня показала заметную поддержку большевистских лозунгов в столице. Начатое на фронте наступление окончилось неудачей и усилило разочарование в продолжении войны. Не смешивайте состав съезда и настроение участников отдельной демонстрации: это разные показатели политического влияния.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|july\":{\"category_id\":\"N05-K01\",\"item_id\":\"july\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"В начале июля обострились противоречия в правительственной коалиции и прошли массовые вооружённые выступления в Петрограде. Власть применила силу, начались преследования большевиков, Ленин перешёл на нелегальное положение. После ухода Львова правительство возглавил А. Ф. Керенский. Период двоевластия завершился, однако усиление правительства оказалось непрочным: война и социальный кризис продолжались. Керенский — глава правительства во время корниловских событий и Октябрьского восстания.\",\"supporting_span\":\"В начале июля обострились противоречия в правительственной коалиции и прошли массовые вооружённые выступления в Петрограде. Власть применила силу, начались преследования большевиков, Ленин перешёл на нелегальное положение. После ухода Львова правительство возглавил А. Ф. Керенский. Период двоевластия завершился, однако усиление правительства оказалось непрочным: война и социальный кризис продолжались. Керенский — глава правительства во время корниловских событий и Октябрьского восстания.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|church\":{\"category_id\":\"N05-K01\",\"item_id\":\"church\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"После Февраля менялись отношения государства и религиозных организаций. Летом была провозглашена свобода совести. В августе 1917 года в Москве начал работу Поместный собор Русской православной церкви. Он восстановил патриаршество; патриархом стал Тихон. Этот процесс продолжался после Октября, но прямо включён в содержание темы 7.2 Навигатора. Не путайте восстановление патриаршества в 1917 году с его учреждением в 1589 году. Дата 21 ноября (4 декабря) 1917 года относится к интронизации Тихона.\",\"supporting_span\":\"После Февраля менялись отношения государства и религиозных организаций. Летом была провозглашена свобода совести. В августе 1917 года в Москве начал работу Поместный собор Русской православной церкви. Он восстановил патриаршество; патриархом стал Тихон. Этот процесс продолжался после Октября, но прямо включён в содержание темы 7.2 Навигатора. Не путайте восстановление патриаршества в 1917 году с его учреждением в 1589 году. Дата 21 ноября (4 декабря) 1917 года относится к интронизации Тихона.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|kornilov\":{\"category_id\":\"N05-K01\",\"item_id\":\"kornilov\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"В августе главнокомандующий Л. Г. Корнилов добивался жёстких мер для восстановления порядка и дисциплины. Движение войск к Петрограду и конфликт с Керенским привели к открытому противостоянию. Против выступления действовали Советы, большевики, агитаторы и железнодорожники; к 30 августа оно было подавлено. Правительство потеряло поддержку справа, а большевики усилили влияние благодаря участию в борьбе против Корнилова. Это объясняет, почему поражение выступления ускорило последующий кризис самого правительства. Л. Г. Корнилов — не адмирал В. А. Корнилов времён Крымской войны.\",\"supporting_span\":\"В августе главнокомандующий Л. Г. Корнилов добивался жёстких мер для восстановления порядка и дисциплины. Движение войск к Петрограду и конфликт с Керенским привели к открытому противостоянию. Против выступления действовали Советы, большевики, агитаторы и железнодорожники; к 30 августа оно было подавлено. Правительство потеряло поддержку справа, а большевики усилили влияние благодаря участию в борьбе против Корнилова. Это объясняет, почему поражение выступления ускорило последующий кризис самого правительства. Л. Г. Корнилов — не адмирал В. А. Корнилов времён Крымской войны.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|republic\":{\"category_id\":\"N05-K01\",\"item_id\":\"republic\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"1 сентября 1917 года Россия была провозглашена республикой. Власть временно сосредоточила Директория во главе с Керенским. Провозглашение республики произошло после корниловского выступления и до Октябрьского восстания. Оно не совпадает по дате с падением монархии: в марте царская власть прекратилась, а формальное провозглашение республики состоялось в сентябре. В заданиях на соответствие это событие связано с Временным правительством и Керенским.\",\"supporting_span\":\"1 сентября 1917 года Россия была провозглашена республикой. Власть временно сосредоточила Директория во главе с Керенским. Провозглашение республики произошло после корниловского выступления и до Октябрьского восстания. Оно не совпадает по дате с падением монархии: в марте царская власть прекратилась, а формальное провозглашение республики состоялось в сентябре. В заданиях на соответствие это событие связано с Временным правительством и Керенским.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|autumn\":{\"category_id\":\"N05-K01\",\"item_id\":\"autumn\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Инфляция, недостаток продовольствия, хозяйственная дезорганизация и усталость от войны подрывали доверие к правительству. В деревне расширялись захваты земли, в армии — дезертирство, в городах — забастовки. Большевики получили большинство в Петроградском и Московском Советах. Председателем Петроградского Совета стал Л. Д. Троцкий. Эта перемена дала большевикам организационную и политическую опору для борьбы за власть. Отношение общества к правительству нельзя объяснять одним лозунгом или одной личностью.\",\"supporting_span\":\"Инфляция, недостаток продовольствия, хозяйственная дезорганизация и усталость от войны подрывали доверие к правительству. В деревне расширялись захваты земли, в армии — дезертирство, в городах — забастовки. Большевики получили большинство в Петроградском и Московском Советах. Председателем Петроградского Совета стал Л. Д. Троцкий. Эта перемена дала большевикам организационную и политическую опору для борьбы за власть. Отношение общества к правительству нельзя объяснять одним лозунгом или одной личностью.\",\"branch\":\"process\",\"official_exam_key\":false},\"N05-K01|octplan\":{\"category_id\":\"N05-K01\",\"item_id\":\"octplan\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Ленин настаивал на вооружённом восстании. В руководстве большевиков существовали разногласия: Л. Б. Каменев и Г. Е. Зиновьев выступили против немедленного перехода к нему. Военно-революционный комитет при Петроградском Совете стал организационным центром подготовки и действий. Троцкий играл важную роль как председатель Совета; в ВРК участвовали также левые эсеры. В задании на соответствие «создание Петроградского ВРК» связано с Троцким. Не отождествляйте этот орган с правительством СНК.\",\"supporting_span\":\"Ленин настаивал на вооружённом восстании. В руководстве большевиков существовали разногласия: Л. Б. Каменев и Г. Е. Зиновьев выступили против немедленного перехода к нему. Военно-революционный комитет при Петроградском Совете стал организационным центром подготовки и действий. Троцкий играл важную роль как председатель Совета; в ВРК участвовали также левые эсеры. В задании на соответствие «создание Петроградского ВРК» связано с Троцким. Не отождествляйте этот орган с правительством СНК.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|october\":{\"category_id\":\"N05-K01\",\"item_id\":\"october\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"24 октября началось занятие ключевых объектов столицы: мостов, вокзалов, почты и телеграфа. К утру 25 октября большая часть Петрограда находилась под контролем сил ВРК. В ночь на 26 октября были арестованы министры Временного правительства в Зимнем дворце. Керенский ранее покинул столицу. Поэтому условная дата события — 25 октября (7 ноября), но последовательность действий охватывает несколько дней. Занятие узлов связи и транспорта позволяло изолировать правительство и управлять городом.\",\"supporting_span\":\"24 октября началось занятие ключевых объектов столицы: мостов, вокзалов, почты и телеграфа. К утру 25 октября большая часть Петрограда находилась под контролем сил ВРК. В ночь на 26 октября были арестованы министры Временного правительства в Зимнем дворце. Керенский ранее покинул столицу. Поэтому условная дата события — 25 октября (7 ноября), но последовательность действий охватывает несколько дней. Занятие узлов связи и транспорта позволяло изолировать правительство и управлять городом.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|congress\":{\"category_id\":\"N05-K01\",\"item_id\":\"congress\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"II Всероссийский съезд Советов открылся в Смольном 25 октября. Меньшевики и правые эсеры ушли со съезда в знак протеста против восстания. Съезд оформил переход власти к Советам, избрал ВЦИК и образовал правительство — Совет народных комиссаров во главе с Лениным. ВЦИК и СНК — разные органы. Первые декреты о мире и земле приняты на этом съезде; их подробное содержание относится также к соседней теме 7.3. Это пересечение обозначено в заданиях, а не скрыто.\",\"supporting_span\":\"II Всероссийский съезд Советов открылся в Смольном 25 октября. Меньшевики и правые эсеры ушли со съезда в знак протеста против восстания. Съезд оформил переход власти к Советам, избрал ВЦИК и образовал правительство — Совет народных комиссаров во главе с Лениным. ВЦИК и СНК — разные органы. Первые декреты о мире и земле приняты на этом съезде; их подробное содержание относится также к соседней теме 7.3. Это пересечение обозначено в заданиях, а не скрыто.\",\"branch\":\"event\",\"official_exam_key\":false},\"N05-K01|leftsr\":{\"category_id\":\"N05-K01\",\"item_id\":\"leftsr\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Левые эсеры поддержали переход власти к Советам и участвовали в работе ВЦИК. Первоначально СНК состоял из большевиков; затем представители левых эсеров вошли в правительство. Учебник связывает формирование коалиции с ноябрём–декабрём 1917 года. Поэтому фраза «после Октября власть сразу и во всех органах была только большевистской» неточна. При сравнении указывайте орган и момент времени. История дальнейшего распада коалиции выходит за рамки основного сюжета этой карточки.\",\"supporting_span\":\"Левые эсеры поддержали переход власти к Советам и участвовали в работе ВЦИК. Первоначально СНК состоял из большевиков; затем представители левых эсеров вошли в правительство. Учебник связывает формирование коалиции с ноябрём–декабрём 1917 года. Поэтому фраза «после Октября власть сразу и во всех органах была только большевистской» неточна. При сравнении указывайте орган и момент времени. История дальнейшего распада коалиции выходит за рамки основного сюжета этой карточки.\",\"branch\":\"process\",\"official_exam_key\":false},\"N05-K01|warland\":{\"category_id\":\"N05-K01\",\"item_id\":\"warland\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"Можно выделить три взаимосвязанных механизма. Продолжение войны сохраняло потери и усталость солдат. Откладывание окончательного аграрного решения не удовлетворяло крестьян и усиливало самовольные захваты земли. Хозяйственный кризис и ухудшение снабжения подрывали поддержку в городах. Политические кризисы и перестановки кабинета не устраняли этих причин. В развёрнутом ответе недостаточно написать «слабость правительства»: нужно показать, какое решение или нерешённый вопрос лишали его поддержки определённых общественных групп.\",\"supporting_span\":\"Можно выделить три взаимосвязанных механизма. Продолжение войны сохраняло потери и усталость солдат. Откладывание окончательного аграрного решения не удовлетворяло крестьян и усиливало самовольные захваты земли. Хозяйственный кризис и ухудшение снабжения подрывали поддержку в городах. Политические кризисы и перестановки кабинета не устраняли этих причин. В развёрнутом ответе недостаточно написать «слабость правительства»: нужно показать, какое решение или нерешённый вопрос лишали его поддержки определённых общественных групп.\",\"branch\":\"process\",\"official_exam_key\":false},\"N05-K01|worker\":{\"category_id\":\"N05-K01\",\"item_id\":\"worker\",\"question\":\"Какое событие или процесс здесь изучается?\",\"text\":\"После Февраля рабочие создавали фабрично-заводские комитеты и пытались контролировать решения администрации предприятий. Рабочий контроль связан с конфликтом вокруг условий труда, производства и власти на";
